// A caller that OMITS a field entirely - rather than sending "" - must get a
// business outcome, not "No such property". An unbound parameter is not a null
// variable in Groovy; it is a missing one, so it has to be asked for by name.
def raw = { n -> binding.hasVariable(n) ? binding.getVariable(n) : null }
def t = { v -> v == null ? '' : v.toString().trim() }
def s  = t(raw('search'))
def mr = t(raw('maxRows'))
// `filter` arrived after this callable was already live. It is read the same way and
// for the same reason: a caller still on the two-input data source sends no `filter`
// at all, and must keep getting the whole roster rather than an engine error.
def rawFilter = raw('filter')

boolean valid = true
String reason = ''

// THE WHOLE ROSTER WHEN NOTHING IS ASKED FOR. This is an export, not a page of the
// screen - the caller's own paging is deliberately ignored, and there is no offset.
// The ceiling is a runaway guard, not a page size: nothing clamps `page.limit` on the
// way through (BaseStorageAction.getPageDetailsOrDefault passes it straight to the
// query), so one fetch really does return everything a realistic roster holds.
// If it is ever hit, the run says TRUNCATED rather than handing back a short file.
int rowCap = 50000
if (!mr.isEmpty()) {
    if (mr ==~ /^\d+$/) { rowCap = Integer.parseInt(mr) } else { valid = false; reason = 'maxRows must be a whole number, got: ' + mr }
}
if (rowCap < 1) rowCap = 1
if (rowCap > 50000) rowCap = 50000

// ---- the filter block -------------------------------------------------------
// The screen sends the platform's own wire shape - {op, values:[{field, op, values}]},
// groups nested by the same rule - and the storage node speaks a DIFFERENT dialect:
// {operator, filters:[{property, filter:{operator, value}}]}. Translating between the
// two is this section's whole job. Sending the wire shape straight through answers
// HTTP 500 "Filter$Op ... op is null" at RUN time, which names no node.
//
// Only the operators the screen can offer are accepted (platform-filter.ts,
// TEXT_OPERATORS). Every one takes exactly one value or none, which is why there is
// no list-valued case: dates and money are NOT filterable here, deliberately, and
// adding one means growing a two-value BETWEEN branch FIRST.
// Collected, not thrown at the first one: a caller fixing three mistakes one refusal
// at a time is the experience this avoids.
def filterProblems = []

def FILTER_FIELDS = ["employeeId","firstName","lastName","name","email","status","region","businessGroup","team"] as Set
def ONE_VALUE_OPS = ['EQUAL', 'NOT_EQUAL', 'ICONTAINS', 'NOT_ICONTAINS', 'CONTAINS', 'NOT_CONTAINS',
                     'STARTS_WITH', 'NOT_STARTS_WITH', 'ENDS_WITH', 'NOT_ENDS_WITH', 'REGEX', 'NOT_REGEX'] as Set
def NO_VALUE_OPS = ['EXISTS', 'MISSING'] as Set
def GROUP_OPS = ['AND', 'OR'] as Set

def parsed = rawFilter
if (parsed instanceof String) {
    // NOT `raw`: this script's head already binds that name to the parameter reader.
    // Manage Titles had the name free; here it is taken, and Groovy refuses the shadow.
    def rawText = parsed.trim()
    if (rawText.isEmpty()) parsed = null
    else {
        try { parsed = new groovy.json.JsonSlurper().parseText(rawText) }
        catch (Exception e) { filterProblems << ('filter is not valid JSON: ' + e.getMessage()); parsed = null }
    }
}
if (parsed instanceof Map && parsed.isEmpty()) parsed = null

def toStorage
toStorage = { node, String path ->
    if (!(node instanceof Map)) { filterProblems << (path + ': a filter node must be an object'); return null }
    def op = (node.op == null) ? '' : String.valueOf(node.op).trim().toUpperCase()
    def field = (node.field == null) ? '' : String.valueOf(node.field).trim()

    // No field means a GROUP. The wire shape carries a group's children in `values`, the
    // same key a leaf uses for its operands - the presence of `field` is the only thing
    // that tells them apart.
    if (field.isEmpty()) {
        if (!GROUP_OPS.contains(op)) { filterProblems << (path + ': a group needs op AND or OR, got "' + op + '"'); return null }
        def kids = []
        def vals = node.values
        if (vals != null && !(vals instanceof List)) { filterProblems << (path + ': values of a group must be a list'); return null }
        (vals ?: []).eachWithIndex { child, i ->
            def c = toStorage(child, path + '.values[' + i + ']')
            if (c != null) kids << c
        }
        // An empty group is not an error - it is a filter the user started and did not
        // finish. Dropping it means "no filter", which is what the screen shows anyway.
        if (kids.isEmpty()) return null
        return [operator: op, filters: kids]
    }

    if (!FILTER_FIELDS.contains(field)) { filterProblems << (path + ': unknown or non-filterable field "' + field + '"'); return null }
    boolean takesValue = ONE_VALUE_OPS.contains(op)
    if (!takesValue && !NO_VALUE_OPS.contains(op)) { filterProblems << (path + ': operator "' + op + '" is not supported for ' + field); return null }

    def leaf = [operator: op]
    if (takesValue) {
        def vals = (node.values instanceof List) ? node.values : (node.values == null ? [] : [node.values])
        def first = vals.findResult { (it == null) ? null : (String.valueOf(it).trim() ?: null) }
        if (first == null) { filterProblems << (path + ': ' + op + ' needs one value'); return null }
        if (op == 'REGEX' || op == 'NOT_REGEX') {
            try { java.util.regex.Pattern.compile(first) }
            catch (Exception e) { filterProblems << (path + ': not a valid regular expression: ' + first); return null }
        }
        leaf.value = first
    }
    return [property: 'properties.' + field, filter: leaf]
}

def filterNode = (parsed == null) ? null : toStorage(parsed, 'filter')

if (!filterProblems.isEmpty()) {
    valid = false
    reason = (reason.isEmpty() ? '' : reason + '; ') + filterProblems.join('; ')
}

// Search and filter are ANDed, exactly as ICM | Manage People LIST does it: the box narrows
// whatever the block already selected. Neither one set means the whole roster, which
// is what the Download button asks for when the screen is showing everything.
//
// This is COPIED GROOVY, not a shared node, and it is the one thing here that can
// silently drift - if the LIST filter changes and this does not, the download stops
// matching the table it came from.
def lf = []
if (!valid) {
    lf << [property: 'id', filter: [operator: 'EQUAL', value: '__invalid_input__']]
} else {
    if (!s.isEmpty()) {
        lf << [operator: 'OR', filters: [
            [property: 'properties.employeeId', filter: [operator: 'ICONTAINS', value: s]],
            [property: 'properties.name',       filter: [operator: 'ICONTAINS', value: s]],
            [property: 'properties.email',      filter: [operator: 'ICONTAINS', value: s]]]]
    }
    if (filterNode != null) lf << filterNode
}

return [valid: valid, reason: reason, search: s, rowCap: rowCap,
        listFilter: [operator: 'AND', filters: lf]]

// Flatten to the row shape the CSV node reads. EVERY value is a String: the CSV
// writer is handed text, and a field never set on a record is MISSING, not null,
// so it defaults to '' - otherwise the column holds "null".
def sv = { m, k -> (m != null && m[k] != null) ? m[k].toString() : '' }

// ONE bulk fetch of Currency, joined here. A file of e_6a9c... ids is not something
// a person can read or re-import, so the CODE is what gets written.
def codes = [:]
if (currencyRows != null) currencyRows.each { c -> codes[String.valueOf(c.id)] = sv(c.properties, 'code') }

// Dates are stored as epoch millis and rendered yyyy-MM-dd in UTC. A spreadsheet
// column holding 1788594607505 is a file nobody can use. UTC because Manage People
// stores UTC midnight for a chosen day - rendering in local time would move a hire
// date across a day boundary.
def fmt = new java.text.SimpleDateFormat('yyyy-MM-dd')
fmt.setTimeZone(java.util.TimeZone.getTimeZone('UTC'))
def dv = { m, k -> (m != null && m[k] != null) ? fmt.format(new Date(m[k] as long)) : '' }

def out = []
if (rows != null) rows.each { r ->
    def p = r.properties
    out << [employeeId: sv(p, 'employeeId'), firstName: sv(p, 'firstName'),
            lastName: sv(p, 'lastName'), name: sv(p, 'name'), email: sv(p, 'email'),
            region: sv(p, 'region'), businessGroup: sv(p, 'businessGroup'),
            team: sv(p, 'team'), status: sv(p, 'status'),
            hireDate: dv(p, 'hireDate'), terminationDate: dv(p, 'terminationDate'),
            currencyCode: codes.get(sv(p, 'currencyId')) ?: '',
            personalCurrencyCode: codes.get(sv(p, 'personalCurrencyId')) ?: '',
            personalTarget: sv(p, 'personalTarget'), salary: sv(p, 'salary')]
}

// `total` is the server's count of everything matching the filter (includeTotalCount
// is on), and it is NOT capped by the fetch limit - so comparing it with what came
// back is what makes a short file impossible to miss. The status is computed HERE
// rather than being a literal on the STOP node, because only this node can know.
int n = out.size()
int tot = (total == null) ? n : (total as int)
boolean truncated = tot > n

return [people: out, total: n, matched: tot, truncated: truncated,
        status: truncated ? 'TRUNCATED' : 'OK',
        message: truncated
            ? ('Incomplete file: ' + n + ' of ' + tot + ' people. Raise maxRows to export the rest.')
            : (n == 0 ? 'No people found; the file has its header row only.'
                      : ('All ' + n + ' person(s) exported.'))]
